// walkthroughLesson — A GENERATED LINE AS A WATCH LESSON (WO-ALL-OPENINGS-01
// P3). An opening the page builds from the games has no hand-written
// LessonScript, so its Watch rung used to leave the page for Learn with Coach,
// whose finish never ticked the rung — Learn, Practice and Play stayed locked.
// The line is generated by the SAME pipeline Learn with Coach uses
// (`generateOpening`: the corpus note leads, the computed beat fills, arrows
// from the note), and its spine — the line the tree walks — is read here as
// the beats the masterclass `LessonPlayer` plays. One pipeline, two players.
import type { LessonBeat, LessonScript } from '../types';
import type { WalkthroughTree, WalkthroughTreeNode } from '../types/walkthroughTree';

function sayOf(node: WalkthroughTreeNode): string {
  const segs = node.narration?.map((s) => s.text.trim()).filter(Boolean) ?? [];
  return (segs.length ? segs.join(' ') : node.idea ?? '').trim();
}

/** The tree's spine (first child at every node, or the child playing `along`'s
 *  move when given) as lesson beats, one per move. */
export function walkthroughLesson(
  tree: WalkthroughTree,
  openingId: string,
  title: string,
  orientation: 'white' | 'black',
  along?: readonly string[],
): LessonScript | null {
  const beats: LessonBeat[] = [];
  const moves: string[] = [];
  let node: WalkthroughTreeNode | undefined = tree.root;
  for (let ply = 0; node; ply += 1) {
    const want = along?.[ply];
    const next: WalkthroughTreeNode | undefined = (want ? node.children.find((c) => c.node.san === want) : node.children[0])?.node;
    if (!next?.san) break;
    moves.push(next.san);
    const segArrows = next.narration?.flatMap((s) => s.arrows ?? []) ?? [];
    const segHighlights = next.narration?.flatMap((s) => s.highlights ?? []) ?? [];
    beats.push({
      id: `${openingId}-${ply}`,
      moves: [...moves],
      say: sayOf(next),
      ...(next.shortIdea ? { sayShort: next.shortIdea } : {}),
      ...(segArrows.length ? { arrows: segArrows.map((a) => ({ from: a.from, to: a.to, color: a.color })) } : {}),
      ...(segHighlights.length ? { highlights: segHighlights.map((h) => ({ square: h.square, color: h.color })) } : {}),
    });
    node = next;
  }
  if (beats.length === 0) return null;
  const words = beats.reduce((n, b) => n + b.say.split(/\s+/).filter(Boolean).length, 0);
  return { openingId, title, minutes: Math.max(1, Math.round(words / 150)), orientation, beats, kind: 'variation' };
}
